def s1_masks(model: nn.Module, target: float) -> dict[str, torch.Tensor]:
    """Pool all eligible weights and zero the `target` fraction with smallest |w|."""
    w = eligible_weights(model)
    all_abs = torch.cat([t.abs().flatten() for t in w.values()])
    k = int(round((1.0 - target) * all_abs.numel()))
    # keep the k LARGEST |w|  ->  zero the (numel - k) smallest
    thresh, _ = all_abs.kthvalue(all_abs.numel() - k + 1)
    masks = {key: (t.abs() >= thresh) for key, t in w.items()}
    # break |w|-ties deterministically so the global fraction is exact:
    # (numel-k) entries must be zeroed; adjust within the tie set if needed.
    zeroed = sum(int((m == 0).sum()) for m in masks.values())
    want = all_abs.numel() - k
    if zeroed != want:
        tie = {key: (t.abs() == thresh) for key, t in w.items()}
        delta = want - zeroed  # >0: more to zero (ties were kept); <0: fewer
        order = sorted(masks, key=lambda key: (int((masks[key] == 0).sum()), key))
        for key in order:
            if delta == 0:
                break
            tmask, tset = masks[key], tie[key]
            if delta > 0 and tset.any():
                idx = torch.nonzero(tset.flatten()).flatten()[:delta]
                tmask.view(-1).index_fill_(0, idx, 0)
                delta -= len(idx)
            elif delta < 0 and tset.any():
                kept = torch.nonzero((tmask == 0) & tset).flatten()[: -delta]
                tmask.view(-1).index_fill_(0, kept, 1)
                delta += len(kept)
    return {key: (m == 1).to(torch.int8) for key, m in masks.items()}

